prefix = '\n#include <pthread.h>\n#include <stdbool.h>\n#include <stdio.h>\n#include <stdlib.h>\n#define DEFINE_SPINLOCK(name) pthread_mutex_t name = PTHREAD_MUTEX_INITIALIZER\n#define raw_local_save_flags(flags) ((flags) = 0)\n#define local_fiq_disable() ((void)0)\n#define raw_local_irq_restore(flags) ((void)(flags))\n#define spin_lock_irqsave(lock, flags) do { (flags) = 0; pthread_mutex_lock(lock); } while (0)\n#define spin_unlock_irqrestore(lock, flags) do { (void)(flags); pthread_mutex_unlock(lock); } while (0)\n#define CONF_AUDIO_MUTE_OP 0x11001000\n#define AUDIO_MUTE 1\n#define AUDIO_UNMUTE 2\n#define HDMITX_TOP_CLK_CNTL 0\n#define HDMITX_DWC_FC_PACKET_TX_EN 1\nstruct hdmitx_dev {\n  int hdmi_init;\n  unsigned int tx_aud_cfg;\n  struct { int (*cntlconfig)(struct hdmitx_dev *, unsigned int, unsigned int); } hwop;\n};\nstatic struct hdmitx_dev hdmitx_device;\nstatic unsigned int registers[2];\nstatic int amute_flag = -1;\nstatic DEFINE_SPINLOCK(audio_mute_lock);\nstatic pthread_mutex_t gate = PTHREAD_MUTEX_INITIALIZER;\nstatic pthread_cond_t condition = PTHREAD_COND_INITIALIZER;\nstatic bool reached, released;\nstatic _Thread_local bool pause_call;\nstatic void hold(void) {\n  if (!pause_call) return;\n  pthread_mutex_lock(&gate);\n  reached = true;\n  pthread_cond_broadcast(&condition);\n  while (!released) pthread_cond_wait(&condition, &gate);\n  pthread_mutex_unlock(&gate);\n  pause_call = false;\n}\nstatic void hdmitx_set_reg_bits(unsigned int addr, unsigned int value,\n                                unsigned int offset, unsigned int len) {\n  unsigned int mask = ((1u << len) - 1u) << offset;\n  registers[addr] = (registers[addr] & ~mask) | ((value << offset) & mask);\n}\n'

suffix = '\nstatic void held_mute_call(bool flag) {\n  hold();\n  audio_mute_op(flag);\n}\n#define audio_mute_op(flag) held_mute_call(flag)\nstatic void reapply(struct hdmitx_dev *hdev) {\nREAPPLY\n}\n#undef audio_mute_op\nstatic void *public_mute(void *unused) {\n  (void)unused; pause_call = true; hdmitx_audio_mute_op(0); return NULL;\n}\nstatic void *mode_reapply(void *unused) {\n  (void)unused; pause_call = true; reapply(&hdmitx_device); return NULL;\n}\nstatic bool trial(void *(*first)(void *), const char *name) {\n  reached = false; released = false; amute_flag = -1;\n  registers[0] = 0; registers[1] = 0; hdmitx_device.tx_aud_cfg = 0;\n  pthread_t thread;\n  if (pthread_create(&thread, NULL, first, NULL)) abort();\n  pthread_mutex_lock(&gate);\n  while (!reached) pthread_cond_wait(&condition, &gate);\n  pthread_mutex_unlock(&gate);\n  hdmitx_audio_mute_op(1);\n  pthread_mutex_lock(&gate);\n  released = true;\n  pthread_cond_broadcast(&condition);\n  pthread_mutex_unlock(&gate);\n  if (pthread_join(thread, NULL)) abort();\n  bool enabled = (registers[0] & 0xc) == 0xc && (registers[1] & 9) == 9;\n  bool agree = (hdmitx_device.tx_aud_cfg != 0) == enabled;\n  printf("%s: %s (desired=%u cache=%d clocks=%x packets=%x)\\n",\n         name, agree ? "PASS" : "FAIL", hdmitx_device.tx_aud_cfg,\n         amute_flag, registers[0], registers[1]);\n  return agree;\n}\nint main(void) {\n  hdmitx_device.hdmi_init = 1; hdmitx_device.hwop.cntlconfig = dispatch;\n  bool public_ok = trial(public_mute, "Public mute publication/backend");\n  bool reapply_ok = trial(mode_reapply, "Mode reapply captured desired state");\n  return public_ok && reapply_ok ? 0 : 1;\n}\n'
